import json
import os

task_id = "task-1a667d7f"
workspace = "/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/seen/play/users/u090/system/state/workspace/programs"
json_file = os.path.join(workspace, task_id, f"{task_id}.json")

# Load demo pairs
with open(json_file) as f:
    demo_pairs = json.load(f)

input_grid = demo_pairs[0]["input"]
output_grid = demo_pairs[0]["output"]

# Find all 9-positions in grid
def find_9_coords(grid):
    coords = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 9:
                coords.append((r, c))
    return coords

# Get all rows with 9s and all cols with 9s
def get_boundary_rows(grid):
    rows = set(r for r, c in find_9_coords(grid))
    return sorted(rows)

def get_boundary_cols(grid):
    cols = set(c for r, c in find_9_coords(grid))
    return sorted(cols)

rows_with_9s = get_boundary_rows(input_grid)
cols_with_9s = get_boundary_cols(input_grid)

print(f"Rows with 9s: {rows_with_9s}")
print(f"Cols with 9s: {cols_with_9s}")

# Find connected components of 9s
def get_connected_9_regions(grid):
    visited = set()
    regions = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 9 and (r, c) not in visited:
                region = []
                queue = [(r, c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    region.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == 9 and (nr, nc) not in visited:
                                queue.append((nr, nc))
                regions.append(region)

    return regions

regions = get_connected_9_regions(input_grid)
print(f"\nNumber of 9-regions: {len(regions)}")
for i, region in enumerate(regions):
    print(f"  Region {i}: {len(region)} cells")
    r_min, r_max = min(r for r,c in region), max(r for r,c in region)
    c_min, c_max = min(c for r,c in region), max(c for r,c in region)
    print(f"    Bounding box: rows {r_min}-{r_max}, cols {c_min}-{c_max}")

